INSERT INTO `articles` (`id`, `title`, `slug`, `content`, `excerpt`, `featured_image`, `published_at`, `created_at`) VALUES
(1, 'Anak Terlambat Bicara', 'anak-terlambat-bicara', '<p>Sekolah Talenta - Anak Berkebutuhan Khusus jenis down syndrom yang mengalami keterlambatan bicara Anak berkebutuhan khusus jenis down syndrom adalah suatu kondisi yang disebabkan oleh adanya kelebihan kromosom pada pasangan dan ditandai dengan retardasi mental serta anomali fisik yang beragam Kromosom merupakan serat serat khusus yang terdapat didalam setiap sel didalam badan manusia dimana terdapat bahan bahan genetik yang menentukan sifat sifat seseorang.</p>\n<p>Kelainan kromosom tertentu dapat mengakibatkan kelainan metabolik yang selanjutnya mempengaruhi pertumbuhan otak secara negatif dan melahirkan retardasi mental. Contohnya adalah Down Syndrom atau mongolisme. Jenis retardasi mental ini pertama kali ditemukan oleh Langdon Down pada tahun 1886 Tingkat retardasi mentalnya berkisar antara sedang sampai berat disebut mongolisme sebab penderitanya sering bermata sipit, mirip orang mongol. Penyebabnya adalah kelainan pada kromosom (adanya trisomi pada kromosom Usia ayah maupun ibu yang sudah lanjut, yakni di atas atau bahkan 50 tahun waktu bayi dikandung atau dilahirkan, berpengaruh terhadap timbulnya kelainan kromosom tersebut.</p>\n<p>Oleh karena itu pada saat wanita menjadi tua, kondisi sel telur tersebut kadang kadang menjadi kurang baik dan pada waktu dibuahi oleh sel telur laki laki, sel benih ini mengalami pembelahan yang kurang sempurna. Anak dengan Down Syndrom dapat dikenali berdasarkan ciri-ciri fisik tertentu, seperti kepalanya kecil bulat (brachicephaly) dan ceper, tidak sempurna Ubun ubunnya tidak lekas tertutup, menjadi keras bahkan sering tidak pernah bisa tertutup sama sekali. Bentuk giginya abnormal, tulang tulang rusuk dan tulang tulang punggung sering mengalami kelainan.</p>\n<p>Bibir tebal atau sumbing, kupingnya sangat besar atau sangat kecil. Kulitnya kering dan kasar, tetapi sering juga lembut dan lunak seperti kulit bayi. Pipinya berwarna kemerah merahan. Tangannya lunak, besar dan lebar seperti mengandung air. Telapak kaki ceper, perut buncit dan pusarnya menonjol keluar. Sendi sendi dan otot ototnya kaku. Selain karakteristik umum tersebut, ada ciri ciri yang spesifik untuk anak down syndrom yakni terdapat ciri fisik khas pada wajahnya.</p>', 'Sekolah Talenta û Anak Berkebutuhan Khusus jenis down syndrom yang mengalami keterlambatan bicara Anak [...]', '/talenta-semarang/assets/images/artikel_anak_terlambat_bicara.png', '2024-07-31', '2026-10-03 09:46:39'),
(2, 'Anak Berkebutuhan Khusus', 'anak-berkebutuhan-khusus', '<p>Sekolah Talenta - Pengertian Anak Berkebutuhan Khusus (ABK) adalah anak yang dalam proses pertumbuhan atau perkembangan mengalami kelainan ataupenyimpangan fisik, mental intelektual, sosial dan atau emosional dibanding dengan anak anak lain seusianya, sehingga mereka memerlukan pelayanan pendidikan khusus.</p>\n<p>Anak Berkebutuhan Khusus (dulu disebut sebagai anak luar biasa) didefinisikan sebagai anak yang memerlukan pendidikan dan layanan khusus untuk mengembangkan potensi kemanusiaan mereka secara sempurna. Dalam dunia pendidikan, kata luar biasa merupakan julukan atau sebutan bagi mereka yang memiliki kekurangan atau mengalami berbagai kelainan dan penyimpangan yang tidak alamiseperti orang normal pada umumnya anak berkebutuhan khusus adalah anak dengan karakteristik khusus yang berbeda dengan anak pada umumnya.</p>\n<p>Dari beberapa pengertian di atas, maka yang dimaksud dengan anak berkebutuhan khusus adalah anak yang mengalami kelainan dengan karakteristik khusus yang membedakannya dengan anak normal pada umumnya serta memerlukan pendidikan khusus sesuai dengan jenis kelainannya.</p>', 'Sekolah Talenta û Pengertian Anak Berkebutuhan Khusus (ABK) adalah anak yang dalam proses pertumbuhan [...]', '/talenta-semarang/assets/images/artikel_2.png', '2024-07-31', '2026-10-03 09:46:39'),
(3, '10 Kesalahan Mendidik Anak', '10-kesalahan-mendidik-anak', '<p>Sekolah Talenta - Meskipun banyak orang tua yang mengetahui, bahwa mendidik anak merupakan tanggung jawab yang besar, tetapi masih banyak orang tua yang lalai dan menganggap remeh masalah ini. Sehingga mengabaikan masalah pendidikan anak ini, sedikitpun tidak menaruh perhatian terhadap perkembangan anak-anaknya.</p>\n<p>Baru kemudian, ketika anak-anak berbuat durhaka, melawan orang tua, atau menyimpang dari aturan agama dan tatanan sosial, banyak orang tua mulai kebakaran jenggot atau justru menyalahkan anaknya. Tragisnya, banyak yang tidak sadar, bahwa sebenarnya orang tuanyalah yang menjadi penyebab utama munculnya sikap durhaka itu.</p>\n<p>Lalai atau salah dalam mendidik anak itu bermacam-macam bentuknya : yang tanpa kita sadari memberi andil munculnya sikap durhaka kepada orang tua, maupun kenakalan remaja.</p>\n<p>Berikut ini sepuluh bentuk kesalahan yang sering dilakukan oleh orang tua dalam mendidik anak-anaknya.</p>\n<p><strong>1. Menumbuhkan Rasa Takut Dan Minder Pada Anak</strong><br>\nKadang, ketika anak menangis, kita menakut-nakuti mereka agar berhenti menangis. Kita takuti mereka dengan gambaran hantu, jin, suara angin dan lain-lain. Dampaknya, anak akan tumbuh menjadi seorang penakut : Takut pada bayangannya sendiri, takut pada sesuatu yang sebenarnya tidak perlu ditakuti. Misalnya takut ke kamar mandi sendiri, takut tidur sendiri karena seringnya mendengar cerita-cerita tentang hantu, jin dan lain-lain.</p>\n<p>Dan yang paling parah tanpa disadari, kita telah menanamkan rasa takut kepada dirinya sendiri. Atau misalnya, kita khawatir ketika mereka jatuh dan ada darah di wajahnya, tangan atau lututnya. Padahal semestinya, kita bersikap tenang dan menampakkan senyuman menghadapi ketakutan anak tersebut. Bukannya justru menakut-nakutinya, menampar wajahnya, atau memarahinya serta membesar-besarkan masalah. Akibatnya, anak-anak semakin keras tangisnya, dan akan terbiasa menjadi takut apabila melihat darah atau merasa sakit.</p>\n<p><strong>2. Mendidiknya Menjadi Sombong, Panjang Lidah, Congkak Terhadap Orang Lain. Dan Itu Dianggap Sebagai Sikap Pemberani</strong><br>\nKesalahan ini merupakan kebalikan point pertama. Yang benar ialah bersikap tengah-tengah, tidak berlebihan dan tidak dikurang-kurangi. Berani tidak harus dengan bersikap sombong atau congkak kepada orang lain. Tetapi, sikap berani yang selaras tempatnya dan rasa takut apabila memang sesuatu itu harus ditakuti. Misalnya : takut berbohong, karena ia tahu, jika Allah tidak suka kepada anak yang suka berbohong, atau rasa takut kepada binatang buas yang membahayakan. Kita didik anak kita untuk berani dan tidak takut dalam mengamalkan kebenaran.</p>\n<p><strong>3. Membiasakan Anak-Anak Hidup Berfoya-foya, Bermewah-mewah Dan Sombong</strong><br>\nDengan kebiasaan ini, sang anak bisa tumbuh menjadi anak yang suka kemewahan, suka bersenang-senang. Hanya mementingkan dirinya sendiri, tidak peduli terhadap keadaan orang lain. Mendidik anak seperti ini dapat merusak fitrah, membunuh sikap istiqomah dalam bersikap zuhud di dunia, membinasakah muru\'ah (harga diri) dan kebenaran.</p>\n<p><strong>4. Selalu Memenuhi Permintaan Anak</strong><br>\nSebagian orang tua ada yang selalu memberi setiap yang diinginkan anaknya, tanpa memikirkan baik dan buruknya bagi anak. Padahal, tidak setiap yang diinginkan anaknya itu bermanfaat atau sesuai dengan usia dan kebutuhannya. Misalnya si anak minta tas baru yang sedang trend, padahal baru sebulan yang lalu orang tua membelikannya tas baru. Hal ini hanya akan menghambur-hamburkan uang. Kalau anak terbiasa terpenuhi segala permintaannya, maka mereka akan tumbuh menjadi anak yang tidak peduli pada nilai uang dan beratnya mencari nafkah. Serta mereka akan menjadi orang yang tidak bisa membelanjakan uangnya dengan baik.</p>\n<p><strong>5. Selalu Memenuhi Permintaan Anak, Ketika Menangis, Terutama Anak Yang Masih Kecil</strong><br>\nSering terjadi, anak kita yang masih kecil minta sesuatu. Jika kita menolaknya karena suatu alasan, ia akan memaksa atau mengeluarkan senjatanya, yaitu menangis. Akhirnya, orang tua akan segera memenuhi permintaannya karena kasihan atau agar anak segera berhenti menangis. Hal ini dapat menyebabkan sang anak menjadi lemah, cengeng dan tidak punya jati diri.</p>\n<p><strong>6. Terlalu Keras Dan Kaku Dalam Menghadapi Mereka, Melebihi Batas Kewajaran</strong><br>\nMisalnya dengan memukul mereka hingga memar, memarahinya dengan bentakan dan cacian, ataupun dengan cara-cara keras lainnya. Ini kadang terjadi ketika sang anak sengaja berbuat salah. Padahal ia (mungkin) baru sekali melakukannya.</p>\n<p><strong>7. Terlalu Pelit Pada Anak-Anak, Melebihi Batas Kewajaran</strong><br>\nAda juga orang tua yang terlalu pelit kepada anak-anaknya, hingga anak-anaknya merasa kurang terpenuhi kebutuhannya. Pada akhirnya mendorong anak-anak itu untuk mencari uang sendiri dengan bebagai cara. Misalnya : dengan mencuri, meminta-minta pada orang lain, atau dengan cara lain. Yang lebih parah lagi, ada orang tua yang tega menitipkan anaknya ke panti asuhan untuk mengurangi beban dirinya. Bahkan, ada pula yang tega menjual anaknya, karena merasa tidak mampu membiayai hidup. Naa\'udzubillah mindzalik</p>\n<p><strong>8. Tidak Mengasihi Dan Menyayangi Mereka, Sehingga Membuat Mereka Mencari Kasih Sayang Diluar Rumah Hingga Menemukan Yang Dicarinya</strong><br>\nFenomena demikian ini banyak terjadi. Telah menyebabkan anak-anak terjerumus ke dalam pergaulan bebas -waiyadzubillah-. Seorang anak perempuan misalnya, karena tidak mendapat perhatian dari keluarganya ia mencari perhatian dari laki-laki di luar lingkungan keluarganya. Dia merasa senang mendapatkan perhatian dari laki-laki itu, karena sering memujinya, merayu dan sebagainya. Hingga ia rela menyerahkan kehormatannya demi cinta semu.</p>\n<p><strong>9. Hanya Memperhatikan Kebutuhan Jasmaninya Saja</strong><br>\nBanyak orang tua yang mengira, bahwa mereka telah memberikan yang terbaik untuk anak-anaknya. Banyak orang tua merasa telah memberikan pendidikan yang baik, makanan dan minuman yang bergizi, pakaian yang bagus dan sekolah yang berkualitas. Sementara itu, tidak ada upaya untuk mendidik anak-anaknya agar beragama secara benar serta berakhlak mulia. Orang tua lupa, bahwa anak tidak cukup hanya diberi materi saja. Anak-anak juga membutuhkan perhatian dan kasih sayang. Bila kasih sayang tidak di dapatkan dirumahnya, maka ia akan mencarinya dari orang lain.</p>\n<p><strong>10. Terlalu Berprasangka Baik Kepada Anak-Anaknya</strong><br>\nAda sebagian orang tua yang selalu berprasangka baik kepada anak-anaknya. Menyangka, bila anak-anaknya baik-baik saja dan merasa tidak perlu ada yang dikhawatirkan, tidak pernah mengecek keadaan anak-anaknya, tidak mengenal teman dekat anaknya, atau apa saja aktifitasnya. Sangat percaya kepada anak-anaknya. Ketika tiba-tiba, mendapati anaknya terkena musibah atau gejala menyimpang, misalnya terkena narkoba, barulah orang tua tersentak kaget. Berusaha menutup-nutupinya serta segera memaafkannya. Akhirnya yang tersisa hanyalan penyesalan tak berguna.</p>\n<p>Demikianlah sepuluh kesalahan yang sering dilakukan orang tua. Yang mungkin kita juga tidak menyadari bila telah melakukannya. Untuk itu, marilah berusaha untuk terus menerus mencari ilmu, terutama berkaitan dengan pendidikan anak, agar kita terhindar dari kesalahan-kesalahan dalam mendidik anak, yang bisa menjadi fatal akibatnya bagi masa depan mereka.</p>', 'Sekolah Talenta û Meskipun banyak orang tua yang mengetahui, bahwa mendidik anak merupakan tanggung [...]', '/talenta-semarang/assets/images/artikel_3.png', '2024-07-31', '2026-10-03 09:46:39'),
(4, 'Manfaat Terapi Tumbuh Kembang Anak', 'manfaat-terapi-tumbuh-kembang', '<p>Setiap anak memiliki keunikan dalam proses tumbuh kembangnya. Ada yang berkembang dengan cepat dalam hal motorik, bahasa, atau sosial, namun ada juga yang memerlukan dukungan lebih untuk mencapai tahap perkembangannya secara optimal. Di sinilah <strong>terapi tumbuh kembang anak</strong> memiliki peran penting.</p>\n\n<h3>Apa Itu Terapi Tumbuh Kembang Anak?</h3>\n<p>Terapi tumbuh kembang adalah serangkaian kegiatan yang dirancang untuk membantu anak mencapai kemampuan fisik, emosional, sosial, dan kognitif sesuai usianya. Terapi ini biasanya melibatkan berbagai ahli seperti terapis okupasi, terapis wicara, psikolog anak, hingga fisioterapis.</p>\n\n<h3>1. Membantu Anak Mencapai Potensi Maksimal</h3>\n<p>Melalui terapi, anak mendapatkan bimbingan terstruktur agar dapat menguasai keterampilan dasar—seperti berbicara, berjalan, menulis, dan bersosialisasi. Pendekatan ini membantu anak mengembangkan kemampuan secara bertahap dan sesuai kebutuhan individunya.</p>\n\n<h3>2. Meningkatkan Kepercayaan Diri Anak</h3>\n<p>Anak yang merasa mampu melakukan sesuatu akan memiliki rasa percaya diri yang lebih tinggi. Terapi membantu anak merasakan keberhasilan kecil setiap sesi, yang menjadi pondasi penting bagi tumbuhnya rasa percaya diri.</p>\n\n<h3>3. Meningkatkan Kemampuan Sosial dan Emosional</h3>\n<p>Selain aspek fisik dan kognitif, terapi juga mengajarkan anak cara berinteraksi, mengatur emosi, dan memahami perasaan orang lain. Ini sangat penting untuk membangun kemampuan adaptasi di lingkungan sekolah maupun sosial.</p>\n\n<h3>4. Deteksi dan Penanganan Dini</h3>\n<p>Salah satu manfaat utama terapi adalah <strong>deteksi dini gangguan tumbuh kembang</strong> seperti keterlambatan bicara, gangguan motorik, autisme, atau ADHD. Semakin cepat ditangani, semakin besar peluang anak untuk berkembang secara optimal.</p>\n\n<h3>5. Mendukung Peran Orang Tua</h3>\n<p>Terapi tidak hanya berfokus pada anak, tetapi juga melibatkan orang tua dalam prosesnya. Dengan pendampingan dan arahan dari terapis, orang tua belajar bagaimana memberikan stimulasi yang tepat di rumah.</p>\n\n<hr style=\"border: none; border-top: 1px solid #ccc; margin: 30px 0;\">\n\n<h3>Kesimpulan</h3>\n<p>Terapi tumbuh kembang anak bukan hanya untuk anak yang mengalami hambatan perkembangan, tetapi juga bermanfaat bagi semua anak agar dapat berkembang secara optimal sesuai potensinya. Dengan dukungan yang tepat sejak dini, setiap anak memiliki kesempatan untuk tumbuh menjadi pribadi yang mandiri, percaya diri, dan bahagia.</p>', 'Setiap anak memiliki keunikan dalam proses tumbuh kembangnya. Ada yang berkembang dengan cepat dalam [...]', '/talenta-semarang/assets/images/artikel_4.png', '2025-11-01', '2026-10-03 09:46:39'),
(5, '3 Penyebab Balita Kurang Mandiri', '3-penyebab-balita-kurang-mandiri', '<p>Sekolah Talenta - Sebagai orang tua, sudah sepantasnya kita mengajarkan anak untuk bisa mandiri. Namun, pada usia berapa mereka sudah mulai bisa diajarkan?</p>\n<p>\"Waktu yang tepat untuk mengajari anak mandiri adalah ketika usia 2-3 tahun. Inilah waktunya si anak senang melakukan berbagai hal sendiri,\" kata Alzena Masykouri, MPsi.</p>\n<p>Dengan melatih kebutuhan anak untuk mandiri sejak dini, dan membantu anak untuk menunjukkan kemampuannya, bahwa ia mampu makan sendiri, pakai baju sendiri, maka ketika anak memasuki usia prasekolah, ia makin terlatih mandiri.</p>\n<p>Bila di usia prasekolah (3-5 tahun), anak masih kurang mandiri, biasanya disebabkan tiga hal berikut.</p>\n<p><strong>1. Kurang mendapat kesempatan</strong></p>\n<p>Orang-orang di lingkungan sekitar, termasuk orangtua, kakek atau nenek, bahkan pekerja rumah tangga, kurang mengakomodasi atau memberikan kesempatan pada anak untuk berlatih mandiri.</p>\n<p>Kalau anak tidak atau hanya sedikit diberikan kesempatan, jangan harap ia akan paham akan sesuatu yang harus ia lakukan untuk dirinya. Jadi, bila di usia dini anak tak mendapat kesempatan untuk mandiri, maka di usia selanjutnya ia pun tidak atau kurang mandiri.</p>\n<p><strong>2. Dianggap \"lama\"</strong></p>\n<p>Orangtua sering tak sabar akan proses kemandirian pada anak. Sebenarnya anak sudah bisa pakai baju sendiri, makan sendiri, pakai sepatu sendiri, tapi melakukannya butuh waktu.</p>\n<p>Nah dengan alasan supaya cepat, orangtua atau pengasuh lah yang kemudian menggantikan peran anak dalam melakukan semua hal tadi. Dengan alasan supaya cepat inilah, tanpa disadari orangtua \"memandulkan\" kemandirian anak.</p>\n<p><strong>3. Dilayani pengasuh atau orangtua</strong></p>\n<p>Ada anak yang selama 24 jam selalu dilayani, baik oleh pengasuhnya maupun ibunya sendiri. Kebiasaan ini membuat anak tak mandiri. Ia selalu memanggil pengasuhnya untuk memenuhi semua kebutuhannya.</p>\n<p>Dalam hal ini pengasuh anak tak bisa disalahkan, karena bagaimana pun ia adalah perpanjangan tangan orangtua, terutama orangtua bekerja. Pengasuh bertindak seperti ini karena diberi tugas oleh orangtua si anak.</p>\n<p>Bagi ibu rumah tangga, karena merasa seharian di rumah, umumnya para ibu ini beralasan \"Buat apa saya ada di rumah kalau tidak mengurus anak?\" Akhirnya semua kebutuhan anak diladeni. Di sisi lain, ibu tak sabar, maka agar semua pekerjaan bisa beres, segala kebutuhan anak dipenuhi dengan campur tangannya.</p>\n<p>Anak usia ini lebih banyak menghabiskan waktu di rumah. Kalaupun bersekolah, ia hanya sekolah tiga jam. Selebihnya, anak belajar dari pengasuhan orangtuanya. Kalau pun anak diajarkan kemandirian di sekolah, ke toilet sendiri dan lain sebagainya, namun kebiasaan di rumah sangat menentukan kemandirian anak.</p>', 'Sekolah Talenta û Sebagai orang tua, sudah sepantasnya kita mengajarkan anak untuk bisa mandiri. [...]', '/talenta-semarang/assets/images/artikel_5.png', '2024-07-31', '2026-10-03 09:46:39'),
(6, 'Metode & Konsep Pengajaran', 'metode-konsep-pengajaran', '\n<style>\n    .metode-intro { margin-bottom: 50px; }\n    .metode-intro p { margin-bottom: 15px; }\n    .sentra-section { margin-bottom: 60px; }\n    .sentra-title { font-size: 1.2rem; font-weight: 700; color: #333; margin-bottom: 15px; }\n    .sentra-text { margin-bottom: 25px; }\n    .img-grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }\n    .img-grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 15px; }\n    .img-single { display: flex; justify-content: center; }\n    .img-single img { max-width: 70%; }\n    .sentra-img { width: 100%; height: auto; aspect-ratio: 4/3; object-fit: cover; border-radius: 5px; box-shadow: 0 4px 10px rgba(0,0,0,0.05); }\n    @media (max-width: 768px) {\n        .img-grid-2, .img-grid-3 { grid-template-columns: 1fr; }\n        .img-single img { max-width: 100%; }\n    }\n</style>\n\n<div class=\"metode-intro\">\n    <p><a href=\"/talenta-semarang/\">Sekolah Talenta</a> - Program kegiatan KB-TK Talenta dirancang berdasarkan pada Kurikulum PAUD dari Diknas dengan pendekatan belajar melalui bermain dan mengembangkan potensi kecerdasan anak.</p>\n    <p>Mendidik anak usia dini membutuhkan banyak kegiatan pembelajaran yang kreatif dan inovatif. Salah satunya adalah kegiatan pembelajaran yang berpusat pada anak yang biasa disebut dengan sentra. Pembelajaran sentra merupakan pembelajaran yang difokuskan pada anak (student center) dan guru berperan sebagai pengawas dan fasilitator. KB-TK Talenta menyediakan pembelajaran sentra yang meliputi :</p>\n</div>\n\n<!-- Sentra 1 -->\n<div class=\"sentra-section\">\n    <h2 class=\"sentra-title\">1. Sentra Keimanan dan Ketaqwaan</h2>\n    <div class=\"sentra-text\">\n        <p>Sentra keimanan dan ketaqwaan merupakan pembelajaran berbagai kegiatan yang berfungsi untuk meningkatkan keimanan dan ketaqwaan peserta didik kepada Tuhan Yang Maha Esa. Dalam sentra ini anak melakukan kegiatan bermain mengenal agama yang dianutnya didampingi oleh guru yang beragama sama dengan anak. KB-TK Talenta merupakan sekolah nasional yang menerima siswa dari semua agama. Sentra ini bertujuan agar peserta didik dapat mengembangkan kemampuan beragama sejak dini dan dapat membentuk pribadi yang cerdas dan berperilaku sesuai norma agama.</p>\n        <p>Setiap hari sebelum mulai pembelajaran semua anak mengikuti kegiatan morning devotion sesuai dengan agama anak.</p>\n    </div>\n    <div class=\"img-grid-2\">\n        <img src=\"/talenta-semarang/assets/images/sentra_1_a.png\" alt=\"Sentra Keimanan 1\" class=\"sentra-img\">\n        <img src=\"/talenta-semarang/assets/images/sentra_1_b.png\" alt=\"Sentra Keimanan 2\" class=\"sentra-img\">\n    </div>\n</div>\n\n<!-- Sentra 2 -->\n<div class=\"sentra-section\">\n    <h2 class=\"sentra-title\">2. Sentra Bahan Alam</h2>\n    <div class=\"sentra-text\">\n        <p>Sentra bahan alam merupakan berbagai kegiatan pembelajaran yang berfungsi untuk meningkatkan kemampuan sensorimotorik, melakukan percobaan sederhana dan meningkatkan rasa cinta kepada alam.</p>\n    </div>\n    <div class=\"img-grid-2\">\n        <img src=\"/talenta-semarang/assets/images/sentra_2_a.png\" alt=\"Sentra Bahan Alam 1\" class=\"sentra-img\">\n        <img src=\"/talenta-semarang/assets/images/sentra_2_b.png\" alt=\"Sentra Bahan Alam 2\" class=\"sentra-img\">\n    </div>\n</div>\n\n<!-- Sentra 3 -->\n<div class=\"sentra-section\">\n    <h2 class=\"sentra-title\">3. Sentra Seni</h2>\n    <div class=\"sentra-text\">\n        <p>Sentra seni bertujuan untuk memberikan kesempatan kepada peserta didik untuk mengembangkan bakat, minat dan keterampilannya. Seperti contoh keterampilan tangan, disini peserta didik diajarkan untuk melipat, menggunting, mengelem, mewarnai, membuat prakarya, dll. Di sentra ini anak meningkatkan kemampuan motorik halus, bermain sambil belajar mengasah rasa keindahan, membangun kemandirian, kerja sama dan tanggung jawab.</p>\n    </div>\n    <div class=\"img-single\">\n        <img src=\"/talenta-semarang/assets/images/sentra_3.png\" alt=\"Sentra Seni\" class=\"sentra-img\">\n    </div>\n</div>\n\n<!-- Sentra 4 -->\n<div class=\"sentra-section\">\n    <h2 class=\"sentra-title\">4. Sentra bermain peran</h2>\n    <div class=\"sentra-text\">\n        <p>Sentra bermain peran sangat mendukung peserta didik pada perkembangan bahasa dan interaksi sosial.</p>\n    </div>\n    <div class=\"img-grid-2\">\n        <img src=\"/talenta-semarang/assets/images/sentra_4_a.png\" alt=\"Sentra Bermain Peran 1\" class=\"sentra-img\">\n        <img src=\"/talenta-semarang/assets/images/sentra_4_b.png\" alt=\"Sentra Bermain Peran 2\" class=\"sentra-img\">\n    </div>\n</div>\n\n<!-- Sentra 5 -->\n<div class=\"sentra-section\">\n    <h2 class=\"sentra-title\">5. Sentra balok</h2>\n    <div class=\"sentra-text\">\n        <p>Sentra balok ini membantu perkembangan anak dalam mengembangkan kemampuan visual dan matematika peserta anak usia dini.</p>\n    </div>\n    <div class=\"img-single\">\n        <img src=\"/talenta-semarang/assets/images/sentra_5.png\" alt=\"Sentra Balok\" class=\"sentra-img\">\n    </div>\n</div>\n\n<!-- Sentra 6 -->\n<div class=\"sentra-section\">\n    <h2 class=\"sentra-title\">6. Sentra Persiapan</h2>\n    <div class=\"sentra-text\">\n        <p>Sentra persiapan menstimulasi anak untuk mengembangkan kemampuan baca, tulis dan hitung. Pembelajaran dengan pendekatan bermain keaksaraan yang menyenangkan.</p>\n    </div>\n    <div class=\"img-grid-3\">\n        <img src=\"/talenta-semarang/assets/images/sentra_6_a.png\" alt=\"Sentra Persiapan 1\" class=\"sentra-img\">\n        <img src=\"/talenta-semarang/assets/images/sentra_6_b.png\" alt=\"Sentra Persiapan 2\" class=\"sentra-img\">\n        <img src=\"/talenta-semarang/assets/images/sentra_6_c.png\" alt=\"Sentra Persiapan 3\" class=\"sentra-img\">\n    </div>\n</div>\n', 'Sekolah Talenta û Program kegiatan Sekolah Talenta dirancang berdasarkan pada Kurikulum dari DikNas dengan [...]', '/talenta-semarang/assets/images/artikel_6.png', '2024-07-31', '2026-10-03 09:46:39');

